const router=require('express').Router();
const mongoose=require('mongoose');
const PDFDocument=require('pdfkit');
const {authenticate,requireTenant,requireModule,requirePermission,allowRoles}=require('../middleware/auth');
const asyncHandler=require('../utils/asyncHandler');
const audit=require('../middleware/audit');
const {Tenant,Branch,Patient,Doctor,Department,Appointment,Admission,AdmissionCharge,BillingSourceLink,LabOrder,Invoice,Payment,Service,TaxConfiguration,PatientDeposit,DepositTransaction,Refund,CreditNote,ExpenseCategory,Expense,DiscountApproval,ChartOfAccount,JournalEntry,LedgerTransaction,Sequence}=require('../models');
const {notifyPatient}=require('../services/notifications');
router.use(require('../middleware/auth').onlyKnownRoutes(router));router.use(authenticate,requireTenant);router.use(requireModule('finance'));
const ADMIN=['hospital_admin','super_admin'];
const isAdmin=req=>ADMIN.includes(req.user.role);
const scoped=(req,extra={})=>({_id:extra._id,tenantId:req.tenantId,...(isAdmin(req)?{}:{branchId:{$in:req.branchIds}}),...extra});
function branchFilter(req){return isAdmin(req)?{}:{branchId:{$in:req.branchIds}}}
function branchAllowed(req,id){return isAdmin(req)||req.branchIds.includes(String(id))}
function fail(res,message,status=400){return res.status(status).json({success:false,message})}
function money(v){return Math.round((Number(v)+Number.EPSILON)*100)/100}
function clean(v,n=500){return String(v??'').trim().slice(0,n)}
async function nextNo(tenantId,kind,session){const key=`${tenantId}:${kind}:${new Date().getFullYear()}`;const x=await Sequence.findOneAndUpdate({key},{$inc:{value:1}},{new:true,upsert:true,setDefaultsOnInsert:true,session});return `${kind}-${new Date().getFullYear()}-${String(x.value).padStart(6,'0')}`}
async function getBranch(req,id){if(!id||!branchAllowed(req,id))return null;return Branch.findOne({_id:id,tenantId:req.tenantId,active:true})}
async function ensureAccounts(tenantId,session){
 const rows=[['1000','Cash and Bank','asset'],['1100','Accounts Receivable','asset'],['2100','GST Payable','liability'],['2200','Patient Deposits','liability'],['4000','Healthcare Service Revenue','income'],['5000','Operating Expenses','expense']];
 const out={};for(const [code,name,type] of rows){let a=await ChartOfAccount.findOneAndUpdate({tenantId,code},{$setOnInsert:{tenantId,code,name,type,system:true}},{new:true,upsert:true,setDefaultsOnInsert:true,session});out[code]=a;}return out;
}
async function postJournal({tenantId,branchId,sourceType,sourceId,description,lines,userId,session}){
 const existing=await JournalEntry.findOne({tenantId,sourceType,sourceId}).session(session);if(existing)return existing;
 const accounts=await ensureAccounts(tenantId,session);const normalized=lines.filter(x=>money(x.debit||0)||money(x.credit||0)).map(x=>({...x,accountId:accounts[x.code]._id,accountCode:x.code,accountName:accounts[x.code].name,debit:money(x.debit||0),credit:money(x.credit||0)}));
 const debit=money(normalized.reduce((s,x)=>s+x.debit,0)),credit=money(normalized.reduce((s,x)=>s+x.credit,0));
 if(!normalized.length||debit<=0||Math.abs(debit-credit)>0.009){const e=new Error('Journal entry is not balanced');e.statusCode=422;throw e}
 const entryNo=await nextNo(tenantId,'JE',session);
 const entry=(await JournalEntry.create([{tenantId,branchId,entryNo,description,sourceType,sourceId,lines:normalized,totalDebit:debit,totalCredit:credit,createdBy:userId}],{session}))[0];
 await LedgerTransaction.insertMany(normalized.map(x=>({tenantId,branchId,journalEntryId:entry._id,accountId:x.accountId,debit:x.debit,credit:x.credit,sourceType,sourceId})),{session});
 return entry;
}
async function buildItems(req,items,branchId){
 if(!Array.isArray(items)||!items.length||items.length>100)return {error:'Add between 1 and 100 invoice items'};
 const out=[];let subtotal=0,tax=0,cgst=0,sgst=0,igst=0;
 for(const raw of items){
  const service=await Service.findOne({_id:raw.serviceId,tenantId:req.tenantId,active:true});
  if(!service)return {error:'A selected service is unavailable'};
  const qty=Number(raw.quantity??1);if(!Number.isFinite(qty)||qty<=0||qty>10000)return {error:'Invalid service quantity'};
  const price=(service.branchPricing||[]).find(x=>String(x.branchId)===String(branchId))?.price??service.standardPrice;
  const gross=money(qty*price),lineDiscount=money(raw.discount||0);if(lineDiscount<0||lineDiscount>gross)return {error:'Invalid item discount'};
  const base=money(gross-lineDiscount);
  let cfg=null;if(service.taxConfigurationId)cfg=await TaxConfiguration.findOne({_id:service.taxConfigurationId,tenantId:req.tenantId,active:true, $or:[{branchId:null},{branchId},{branchId:{$exists:false}}]});
  let rate=cfg?.exempt?0:Number(cfg?.rate||0);if(rate<0||rate>100)return {error:'Invalid tax configuration'};
  let taxAmount=cfg?.inclusive?money(base-(base/(1+rate/100))):money(base*rate/100);
  const taxType=cfg?.taxType||'none';let itemCgst=0,itemSgst=0,itemIgst=0;
  if(taxType==='cgst_sgst'){itemCgst=money(taxAmount/2);itemSgst=money(taxAmount-itemCgst)}
  if(taxType==='igst')itemIgst=taxAmount;
  const itemBase=cfg?.inclusive?money(base-taxAmount):base;
  subtotal+=itemBase;tax+=taxAmount;cgst+=itemCgst;sgst+=itemSgst;igst+=itemIgst;
  out.push({serviceId:service._id,description:service.name,category:service.category,quantity:qty,unitPrice:money(price),discount:lineDiscount,taxRate:rate,taxType,taxInclusive:!!cfg?.inclusive,taxAmount,amount:money(itemBase+taxAmount),hsnSac:service.hsnSac||cfg?.hsnSac||''});
 }
 const invoiceDiscount=money(req.body.discount||0);
 const preDiscount=money(subtotal);
 if(invoiceDiscount<0||invoiceDiscount>preDiscount)return {error:'Invoice discount exceeds subtotal'};
 if(invoiceDiscount>0){
  const roleLimit=req.user.role==='receptionist'?0.05:req.user.role==='branch_admin'?0.1:req.user.role==='accountant'?0.2:1;
  const pct=preDiscount?invoiceDiscount/preDiscount:0;
  if(pct>roleLimit&&!req.permissions?.includes('billing.discount.override')&&!req.permissions?.includes('*'))return {error:'Discount exceeds your approval limit. Request manager approval.',approvalRequired:true};
  let newTax=0,newCgst=0,newSgst=0,newIgst=0;
  for(const item of out){
   const allocation=preDiscount?money(invoiceDiscount*((item.amount-item.taxAmount)/preDiscount)):0;
   const oldGross=money(item.amount-allocation);let base,taxPart;
   if(item.taxInclusive&&item.taxRate>0){taxPart=money(oldGross-(oldGross/(1+item.taxRate/100)));base=money(oldGross-taxPart)}
   else{base=money(oldGross-item.taxAmount);taxPart=money(base*item.taxRate/100)}
   item.taxAmount=taxPart;item.amount=money(base+taxPart);
   if(item.taxType==='cgst_sgst'){const half=money(taxPart/2);newCgst+=half;newSgst+=money(taxPart-half)}
   if(item.taxType==='igst')newIgst+=taxPart;
   newTax+=taxPart;
  }
  tax=money(newTax);cgst=money(newCgst);sgst=money(newSgst);igst=money(newIgst);
 }
 const total=money(preDiscount-invoiceDiscount+tax);
 return {items:out,subtotal:preDiscount,discount:invoiceDiscount,tax:money(tax),cgst:money(cgst),sgst:money(sgst),igst:money(igst),total};
}
router.get('/financial/patients',requirePermission('billing.view'),asyncHandler(async(req,res)=>{const filter={tenantId:req.tenantId,...(isAdmin(req)?{}:{branchId:{$in:req.branchIds}})};if(req.query.q)filter.$or=[{firstName:{$regex:clean(req.query.q,60),'$options':'i'}},{lastName:{$regex:clean(req.query.q,60),'$options':'i'}},{uhid:{$regex:clean(req.query.q,60),'$options':'i'}}];const data=await Patient.find(filter).select('firstName lastName uhid branchId').sort({createdAt:-1}).limit(100).lean();res.json({success:true,data})}));
router.get('/financial/dashboard',requirePermission('billing.view'),asyncHandler(async(req,res)=>{
 const now=new Date(),from=req.query.from?new Date(req.query.from):new Date(now.getFullYear(),now.getMonth(),1),to=req.query.to?new Date(req.query.to):now;
 if(!Number.isFinite(from.getTime())||!Number.isFinite(to.getTime())||from>to)return fail(res,'Invalid date range',422);
 const branchId=req.query.branchId;if(branchId&&!branchAllowed(req,branchId))return fail(res,'Branch access denied',403);
 const match={tenantId:new mongoose.Types.ObjectId(req.tenantId),createdAt:{$gte:from,$lte:to},...(branchId?{branchId:new mongoose.Types.ObjectId(branchId)}:(!isAdmin(req)?{branchId:{$in:req.branchIds.map(x=>new mongoose.Types.ObjectId(x))}}:{}))};
 const invoiceMatch={...match,status:{$in:['issued','unpaid','partial','partially_paid','paid','overdue','refunded']}};
 const [inv,pay,exp,recent,refunds]=await Promise.all([
 Invoice.aggregate([{$match:invoiceMatch},{$group:{_id:'$invoiceType',billed:{$sum:'$total'},paid:{$sum:'$paid'},credits:{$sum:'$creditNoteTotal'},count:{$sum:1}}}]),
 Payment.aggregate([{$match:{...match,$or:[{status:'succeeded'},{status:{$exists:false}}]}},{$group:{_id:'$method',amount:{$sum:'$amount'},count:{$sum:1}}}]),
 Expense.aggregate([{$match:{...match,status:'paid'}},{$group:{_id:null,total:{$sum:'$amount'}}}]),
 Invoice.find({...invoiceMatch}).populate('patientId','firstName lastName uhid').sort({createdAt:-1}).limit(8).lean(),
 Refund.aggregate([{$match:{...match,status:'processed'}},{$group:{_id:null,total:{$sum:'$amount'}}}])
 ]);
 const billed=money(inv.reduce((s,x)=>s+x.billed,0)),collected=money(pay.reduce((s,x)=>s+x.amount,0)),expenses=money(exp[0]?.total||0);
 res.json({success:true,data:{billed,collected,outstanding:money(Math.max(0,inv.reduce((s,x)=>s+x.billed-x.paid-(x.credits||0),0))),expenses,net:money(collected-expenses),refunds:money(refunds[0]?.total||0),byInvoiceType:inv,paymentMethods:pay,recentInvoices:recent}});
}));
