router.post('/tax-configurations',requirePermission('billing.tax.manage'),audit('billing.tax.created','tax_configuration'),asyncHandler(async(req,res)=>{const rate=Number(req.body.rate||0);if(!clean(req.body.name,120)||!Number.isFinite(rate)||rate<0||rate>100||!['none','cgst_sgst','igst'].includes(req.body.taxType||'none'))return fail(res,'Invalid tax configuration',422);const branchId=req.body.branchId||null;if(branchId&&!await getBranch(req,branchId))return fail(res,'Branch access denied',403);const x=await TaxConfiguration.create({tenantId:req.tenantId,branchId,name:clean(req.body.name,120),taxType:req.body.taxType||'none',rate,inclusive:!!req.body.inclusive,exempt:!!req.body.exempt,hsnSac:clean(req.body.hsnSac,32),createdBy:req.user._id});res.status(201).json({success:true,data:x})}));
router.patch('/tax-configurations/:id',requirePermission('billing.tax.manage'),audit('billing.tax.updated','tax_configuration'),asyncHandler(async(req,res)=>{const x=await TaxConfiguration.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)});if(!x)return fail(res,'Tax configuration not found',404);if(req.body.rate!==undefined){const n=Number(req.body.rate);if(!Number.isFinite(n)||n<0||n>100)return fail(res,'Tax rate must be between 0 and 100',422);x.rate=n}if(req.body.name!==undefined)x.name=clean(req.body.name,120);if(req.body.taxType!==undefined){if(!['none','cgst_sgst','igst'].includes(req.body.taxType))return fail(res,'Invalid tax type',422);x.taxType=req.body.taxType}if(req.body.inclusive!==undefined)x.inclusive=!!req.body.inclusive;if(req.body.exempt!==undefined)x.exempt=!!req.body.exempt;if(req.body.active!==undefined)x.active=!!req.body.active;await x.save();res.json({success:true,data:x})}));
