router.post('/invoices/:id/finalize',requirePermission('billing.create'),audit('invoice.finalized','invoice'),asyncHandler(async(req,res)=>{const session=await mongoose.startSession();let invoice;try{await session.withTransaction(async()=>{invoice=await Invoice.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)}).session(session);if(!invoice){const e=new Error('Invoice not found');e.statusCode=404;throw e}if(invoice.status!=='draft'){const e=new Error('Only draft invoices can be finalized');e.statusCode=409;throw e}if(invoice.total<=0){const e=new Error('Invoice total must be greater than zero');e.statusCode=422;throw e}invoice.status='issued';invoice.issuedAt=new Date();invoice.finalizedBy=req.user._id;await invoice.save({session});await postJournal({tenantId:req.tenantId,branchId:invoice.branchId,sourceType:'invoice',sourceId:invoice._id,description:`Invoice ${invoice.invoiceNo}`,lines:[{code:'1100',debit:invoice.total},{code:'4000',credit:money(invoice.subtotal-invoice.discount)},{code:'2100',credit:invoice.tax}],userId:req.user._id,session})})}finally{await session.endSession()}await notifyPatient({tenantId:req.tenantId,patientId:invoice.patientId,branchId:invoice.branchId,category:'invoice',title:'Invoice issued',message:`Invoice ${invoice.invoiceNo} is now available.`,link:'/invoices'});res.json({success:true,data:invoice})}));
