router.get('/payments/:id/receipt.pdf',requirePermission('billing.view'),asyncHandler(async(req,res)=>{const payment=await Payment.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req),$or:[{status:'succeeded'},{status:{$exists:false}}]}).populate('patientId','firstName lastName uhid').populate('invoiceId','invoiceNo').populate('branchId','name address city state').lean();if(!payment)return fail(res,'Payment receipt not found',404);const doc=new PDFDocument({size:'A5',margin:36,info:{Title:`Receipt ${payment._id}`,Author:'CareFlow'}});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="receipt-${payment._id}.pdf"`);doc.pipe(res);doc.fillColor('#173F35').fontSize(20).text(payment.branchId?.name||'Healthcare Provider');doc.fillColor('#333').fontSize(10).text([payment.branchId?.address,payment.branchId?.city,payment.branchId?.state].filter(Boolean).join(', '));doc.moveDown().fontSize(16).text('PAYMENT RECEIPT');doc.fontSize(10).text(`Receipt: ${payment._id}`).text(`Date: ${new Date(payment.paidAt||payment.createdAt).toLocaleString('en-IN')}`).text(`Patient: ${payment.patientId?.firstName||''} ${payment.patientId?.lastName||''} · ${payment.patientId?.uhid||''}`).text(`Invoice: ${payment.invoiceId?.invoiceNo||'Patient deposit'}`).moveDown().fontSize(18).fillColor('#173F35').text(`Amount received: ₹${Number(payment.amount).toFixed(2)}`).fillColor('#333').fontSize(10).text(`Method: ${payment.method}`).text(`Reference: ${payment.reference||payment.transactionId||'—'}`).moveDown().text('Payment status: Successful');doc.end()}));
router.get('/reports/outstanding',requirePermission('reports.view'),asyncHandler(async(req,res)=>{const data=await Invoice.find({tenantId:req.tenantId,...branchFilter(req),status:{$in:['issued','unpaid','partial','partially_paid','overdue']}}).populate('patientId','firstName lastName uhid phone').sort({dueAt:1,createdAt:1}).limit(500).lean();res.json({success:true,data:data.map(x=>({...x,balance:money(x.total-x.paid-(x.creditNoteTotal||0)),isOverdue:!!(x.dueAt&&new Date(x.dueAt)<new Date()&&x.total>x.paid+(x.creditNoteTotal||0))}))})}));
router.get('/reports/expenses',requirePermission('reports.view'),asyncHandler(async(req,res)=>{const from=req.query.from?new Date(req.query.from):new Date(new Date().getFullYear(),new Date().getMonth(),1),to=req.query.to?new Date(req.query.to):new Date();const data=await Expense.aggregate([{$match:{tenantId:new mongoose.Types.ObjectId(req.tenantId),expenseDate:{$gte:from,$lte:to},...(!isAdmin(req)?{branchId:{$in:req.branchIds.map(x=>new mongoose.Types.ObjectId(x))}}:{})}},{$group:{_id:{category:'$category',status:'$status'},amount:{$sum:'$amount'},count:{$sum:1}}},{$sort:{'_id.category':1}}]);res.json({success:true,data})}));
