router.get('/reports/revenue',requirePermission('reports.view'),asyncHandler(async(req,res)=>{const from=req.query.from?new Date(req.query.from):new Date(new Date().getFullYear(),new Date().getMonth(),1),to=req.query.to?new Date(req.query.to):new Date(),groupBy=req.query.groupBy||'invoiceType';const groupFields={invoiceType:'$invoiceType',doctor:'$doctorId',department:'$departmentId',service:'$items.serviceId'};if(!groupFields[groupBy])return fail(res,'Unsupported revenue grouping',422);const rows=await Invoice.aggregate([{$match:{tenantId:new mongoose.Types.ObjectId(req.tenantId),createdAt:{$gte:from,$lte:to},status:{$in:['issued','unpaid','partial','partially_paid','paid','overdue','refunded']},...(!isAdmin(req)?{branchId:{$in:req.branchIds.map(x=>new mongoose.Types.ObjectId(x))}}:{})}},{$unwind:'$items'},{$group:{_id:groupFields[groupBy],amount:{$sum:'$items.amount'},quantity:{$sum:'$items.quantity'},invoices:{$addToSet:'$_id'}}},{$project:{amount:1,quantity:1,invoiceCount:{$size:'$invoices'}}},{$sort:{amount:-1}}]);res.json({success:true,data:rows})}));
router.get('/invoices/:id/pdf',requirePermission('billing.view'),asyncHandler(async(req,res)=>{const inv=await Invoice.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)}).populate('patientId','firstName lastName uhid phone address').populate('branchId','name address city state phone gstin').populate('doctorId','name qualifications registrationNo').lean();if(!inv)return fail(res,'Invoice not found',404);const payments=await Payment.find({tenantId:req.tenantId,invoiceId:inv._id,$or:[{status:'succeeded'},{status:{$exists:false}}]}).sort({createdAt:1}).lean();const doc=new PDFDocument({size:'A4',margin:46,info:{Title:`Invoice ${inv.invoiceNo}`,Author:'CareFlow'}});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${inv.invoiceNo}.pdf"`);doc.pipe(res);doc.fillColor('#173F35').fontSize(22).text(inv.branchId?.name||'Healthcare Provider');doc.fillColor('#333').fontSize(9).text([inv.branchId?.address,inv.branchId?.city,inv.branchId?.state,inv.branchId?.phone,inv.branchId?.gstin].filter(Boolean).join(' · '));doc.moveDown().fontSize(18).text(`INVOICE ${inv.invoiceNo}`);doc.fontSize(10).text(`Date: ${new Date(inv.createdAt).toLocaleDateString('en-IN')}    Status: ${inv.status}`);doc.moveDown().text(`Patient: ${inv.patientId?.firstName||''} ${inv.patientId?.lastName||''} (${inv.patientId?.uhid||''})`);doc.text(`Phone: ${inv.patientId?.phone||'—'}    Type: ${inv.invoiceType||'OPD'}`);if(inv.doctorId)doc.text(`Doctor: ${inv.doctorId.name||'—'} · ${inv.doctorId.registrationNo||''}`);doc.moveDown();doc.fontSize(9).text('Description                                      Qty        Rate          Amount');doc.moveTo(46,doc.y+4).lineTo(550,doc.y+4).stroke();doc.moveDown(0.8);for(const item of inv.items||[]){doc.text(`${clean(item.description,48)}    ${item.quantity}       ₹${Number(item.unitPrice).toFixed(2)}       ₹${Number(item.amount).toFixed(2)}`)}doc.moveDown().text(`Subtotal: ₹${Number(inv.subtotal).toFixed(2)}`,{align:'right'}).text(`Discount: ₹${Number(inv.discount).toFixed(2)}`,{align:'right'}).text(`CGST: ₹${Number(inv.cgst||0).toFixed(2)}`,{align:'right'}).text(`SGST: ₹${Number(inv.sgst||0).toFixed(2)}`,{align:'right'}).text(`IGST: ₹${Number(inv.igst||0).toFixed(2)}`,{align:'right'}).text(`Total tax: ₹${Number(inv.tax).toFixed(2)}`,{align:'right'}).fontSize(13).fillColor('#173F35').text(`Total: ₹${Number(inv.total).toFixed(2)}`,{align:'right'}).fillColor('#333').fontSize(10).text(`Paid: ₹${Number(inv.paid).toFixed(2)}    Balance: ₹${Number(inv.total-inv.paid-(inv.creditNoteTotal||0)).toFixed(2)}`,{align:'right'});doc.moveDown().fontSize(9).text(`Payment history: ${payments.map(x=>`${new Date(x.paidAt||x.createdAt).toLocaleDateString('en-IN')} ${x.method} ₹${Number(x.amount).toFixed(2)}`).join(' · ')||'No payments recorded'}`);doc.moveDown(2).fontSize(8).text('This document is generated from CareFlow financial records. No digital signature is implied.');doc.end()}));
router.post('/admissions/:id/discharge',requirePermission('admissions.manage'),allowRoles('hospital_admin','branch_admin'),audit('admission.discharged','admission'),asyncHandler(async(req,res)=>{const summary=clean(req.body.dischargeSummary,20000);if(summary.length<5)return fail(res,'A discharge summary is required',422);const admission=await Admission.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req),status:'admitted'});if(!admission)return fail(res,'Active admission not found',404);admission.status='discharged';admission.dischargedAt=new Date();admission.dischargeSummary=summary;await admission.save();res.json({success:true,data:admission,message:'Admission discharged. Outstanding billing does not prevent discharge.'})}));
router.get('/admissions',requirePermission('billing.view'),asyncHandler(async(req,res)=>{const filter={tenantId:req.tenantId,...branchFilter(req),...(req.query.status==='all'?{}:{status:'admitted'})};const data=await Admission.find(filter).populate('patientId','firstName lastName uhid').sort({admittedAt:-1}).limit(300).lean();res.json({success:true,data})}));
router.get('/admissions/:id/billing',requirePermission('billing.view'),asyncHandler(async(req,res)=>{const admission=await Admission.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)}).populate('patientId','firstName lastName uhid').lean();if(!admission)return fail(res,'Admission not found',404);const [charges,invoices]=await Promise.all([AdmissionCharge.find({tenantId:req.tenantId,admissionId:admission._id}).sort({serviceDate:1}).lean(),Invoice.find({tenantId:req.tenantId,admissionId:admission._id}).sort({createdAt:1}).lean()]);res.json({success:true,data:{admission,invoices,charges,total:money(charges.reduce((s,i)=>s+i.amount,0)),invoiced:money(charges.filter(c=>c.invoicedAt).reduce((s,c)=>s+c.amount,0)),paid:money(invoices.reduce((s,i)=>s+i.paid,0))}})}));
router.post('/admissions/:id/charges',requirePermission('billing.create'),audit('ipd.charge.recorded','admission_charge'),asyncHandler(async(req,res)=>{const admission=await Admission.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)});if(!admission||admission.status!=='admitted')return fail(res,'Active admission not found',404);const service=await Service.findOne({_id:req.body.serviceId,tenantId:req.tenantId,active:true});const qty=Number(req.body.quantity||1);if(!service||!Number.isFinite(qty)||qty<=0||qty>10000)return fail(res,'Select a valid service and quantity',422);const built=await buildItems(req,[{serviceId:service._id,quantity:qty}],admission.branchId);if(built.error)return fail(res,built.error,422);const item=built.items[0];const charge=await AdmissionCharge.create({tenantId:req.tenantId,branchId:admission.branchId,admissionId:admission._id,patientId:admission.patientId,serviceId:service._id,category:service.category,description:service.name,quantity:qty,unitPrice:item.unitPrice,subtotal:money(built.subtotal),taxAmount:money(built.tax),taxRate:item.taxRate,taxType:item.taxType,cgst:built.cgst,sgst:built.sgst,igst:built.igst,amount:money(built.total),serviceDate:req.body.serviceDate||new Date(),recordedBy:req.user._id});res.status(201).json({success:true,data:charge})}));
router.post('/admissions/:id/final-invoice',requirePermission('billing.create'),audit('ipd.final_invoice.created','invoice'),asyncHandler(async(req,res)=>{const admission=await Admission.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)});if(!admission)return fail(res,'Admission not found',404);if(admission.status!=='discharged')return fail(res,'Final IPD bill can only be created after recorded discharge',409);const charges=await AdmissionCharge.find({tenantId:req.tenantId,admissionId:admission._id,invoicedAt:null});if(!charges.length)return fail(res,'No unbilled admission charges are available',422);const session=await mongoose.startSession();let inv;try{await session.withTransaction(async()=>{const no=await nextNo(req.tenantId,'INV',session);const items=charges.map(c=>({serviceId:c.serviceId,sourceType:'admission_charge',sourceId:c._id,description:c.description,category:c.category,quantity:c.quantity,unitPrice:c.unitPrice,amount:c.amount,discount:0,taxRate:c.taxRate||0,taxType:c.taxType||'none',taxAmount:c.taxAmount||0}));const subtotal=money(charges.reduce((s,x)=>s+Number(x.subtotal||x.amount),0)),tax=money(charges.reduce((s,x)=>s+Number(x.taxAmount||0),0)),total=money(charges.reduce((s,x)=>s+Number(x.amount),0));inv=(await Invoice.create([{tenantId:req.tenantId,branchId:admission.branchId,patientId:admission.patientId,admissionId:admission._id,invoiceNo:no,invoiceType:'ipd',items,subtotal,discount:0,tax,cgst:money(charges.reduce((s,x)=>s+Number(x.cgst||0),0)),sgst:money(charges.reduce((s,x)=>s+Number(x.sgst||0),0)),igst:money(charges.reduce((s,x)=>s+Number(x.igst||0),0)),total,status:'draft',notes:'FINAL_IPD',createdBy:req.user._id}],{session}))[0];const marked=await AdmissionCharge.updateMany({_id:{$in:charges.map(c=>c._id)},tenantId:req.tenantId,invoicedAt:null},{$set:{invoicedAt:new Date(),invoiceId:inv._id}},{session});if(marked.modifiedCount!==charges.length){const e=new Error('Admission charges changed during invoice generation; retry');e.statusCode=409;throw e}})}finally{await session.endSession()}res.status(201).json({success:true,data:inv})}));
router.post('/source-charges/lab-orders/:id',requirePermission('billing.create'),audit('billing.lab_order_charged','invoice'),asyncHandler(async(req,res)=>{const order=await LabOrder.findOne({_id:req.params.id,tenantId:req.tenantId,...branchFilter(req)});if(!order)return fail(res,'Lab order not found',404);const service=await Service.findOne({_id:req.body.serviceId,tenantId:req.tenantId,category:'laboratory',active:true});if(!service)return fail(res,'Select a configured laboratory service',422);const session=await mongoose.startSession();let inv;try{await session.withTransaction(async()=>{const exists=await BillingSourceLink.findOne({tenantId:req.tenantId,sourceType:'lab_order',sourceId:order._id}).session(session);if(exists){const e=new Error('This lab order has already been billed');e.statusCode=409;throw e}const built=await buildItems(req,[{serviceId:service._id,quantity:1}],order.branchId);if(built.error){const e=new Error(built.error);e.statusCode=422;throw e}const no=await nextNo(req.tenantId,'INV',session);inv=(await Invoice.create([{tenantId:req.tenantId,branchId:order.branchId,patientId:order.patientId,invoiceNo:no,invoiceType:'laboratory',items:built.items.map(x=>({...x,sourceType:'lab_order',sourceId:order._id})),subtotal:built.subtotal,discount:built.discount,tax:built.tax,cgst:built.cgst,sgst:built.sgst,igst:built.igst,total:built.total,status:'draft',createdBy:req.user._id}],{session}))[0];await BillingSourceLink.create([{tenantId:req.tenantId,branchId:order.branchId,sourceType:'lab_order',sourceId:order._id,patientId:order.patientId,invoiceId:inv._id,createdBy:req.user._id}],{session})})}catch(e){if(e.code===11000)return fail(res,'This lab order has already been billed',409);throw e}finally{await session.endSession()}res.status(201).json({success:true,data:inv})}));
